import {$,clear,el,formDataObject} from './literary-core-dom.js';import {SearchService} from './literary-services-search-service.js';import {events} from '../core/event-bus.js';import {router} from './literary-core-router.js';import {userMessage} from './literary-core-errors.js';
function renderResults(items=[]){const host=$('#global-search-results');clear(host);if(!items.length){host.append(el('p',{text:'No results.'}));return;}const ul=el('ul');for(const item of items){const li=el('li'),b=el('button',{type:'button',text:item.title||item.name||item.label||item.type||'Result'});b.addEventListener('click',()=>{const route=item.route||({node:'manuscript',entity:'world',timeline:'timeline',note:'organizer',issue:'continuity'}[item.type]||'search');$('#global-search-dialog').close();router.go(route,{result:item});});li.append(b,item.snippet?el('p',{text:item.snippet}):'');ul.append(li);}host.append(ul);}
export function installSearchController(){$('#global-search-button')?.addEventListener('click',()=>{$('#global-search-dialog').showModal();$('#global-search-dialog input[type=search]')?.focus();});$('#global-search-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=formDataObject(e.currentTarget);try{const r=await SearchService.global(data.query,{crossProject:Boolean(data.crossProject)});renderResults(r.results||r.items||[]);}catch(error){renderResults([]);$('#global-search-results').prepend(el('p',{role:'alert',text:userMessage(error)}));}});events.on('command:search',()=>$('#global-search-button')?.click());}
export async function searchView(){document.querySelector('#global-search-button')?.click();}
